// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    SimpleWallet c;
    Recorder rec;

    function setUp() public {
        c = new SimpleWallet();
        rec = new Recorder();
    }

    function testFuzz_property(uint256 amount, bytes calldata data) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0);
        vm.assume(amount <= type(uint128).max);
        vm.assume(data.length <= 32);

        // fund the contract so the transfer is admissible
        vm.deal(address(this), amount);
        (bool okPay,) = address(c).call{value: amount}("");
        require(okPay, "funding failed");

        uint256 before = rec.totalReceived();

        vm.prank(c.owner());
        c.sendMoney(address(rec), amount, data);

        // General rule: every admissible sendMoney delivers exactly _value wei
        // to the designated counterparty; the recording helper accumulates it.
        assertTrue(rec.totalReceived() == before + amount);
    }
}

contract Recorder {
    uint256 public totalReceived;

    fallback() external payable {
        totalReceived += msg.value;
    }

    receive() external payable {
        totalReceived += msg.value;
    }
}
